import {ac,aerBrand,aerScene,aerTail} from './aer-art.js';
import {aerCarriers,aerLinks,aerAsset} from './aer-content.js';
import {canAnimate} from './motion-state.js';
const actions=()=>`<div class="aer-actions"><a href="${aerLinks.site}" target="_blank" rel="noopener noreferrer">${ac('打开 AER','Open AER')} <span>↗</span><small>${ac('授权访问','AUTHORISED ACCESS')}</small></a><a href="${aerLinks.post}">${ac('阅读制作手记','Read the departure notes')} <span>↗</span></a></div>`;
export function aerCard(carrier='EK'){
  return `<article class="exhibit aer-exhibit" id="project-aer" data-aer-display data-aer-airline="${carrier}"><div class="aer-edition"><span>${aerBrand} CHEFZC / THE DEPARTURE COLLECTION</span><span>NO. 09 <i>·</i> AER 1.0</span></div><div class="aer-overture"><div class="aer-overture-copy"><span class="aer-overline">FLIGHT, THOUGHTFULLY</span><h3 class="aer-wordmark">aer<span>®</span></h3><p class="aer-hero-line">${ac('让下一程，<br><em>更像你。</em>','A little closer.<br><em>A little more you.</em>')}</p><p class="aer-hero-deck">${ac('把路线写进天空，把自己的节奏留在选择里。<br>一座关于出发、玻璃与好奇心的旅行空间。','Routes written in the sky. Your rhythm, kept in every choice.<br>A space for departure, glass and curiosity.')}</p><div class="aer-glass-caption"><i></i><span>COLOURLESS GLASS<br>COLOURED BY THE WORLD</span></div></div><div class="aer-sculpture">${aerScene({carrier})}<div class="aer-carrier-caption"><span data-tail-caption>${aerCarriers[carrier].name}</span><small>${ac('原涂装 / 光学标本','ORIGINAL LIVERY / OPTICAL SPECIMEN')}</small></div></div></div><div class="aer-curation-bar"><div><span class="aer-overline">THE TAIL COLLECTION</span><p>${ac('不同天空，同一种向往。','Different skies. Your own direction.')}</p></div><div class="aer-carrier-controls" role="group" aria-label="${ac('切换玻璃尾翼','Choose a glass tail')}">${Object.entries(aerCarriers).map(([code,c])=>`<button type="button" data-aer-airline-button="${code}" aria-pressed="${code===carrier}" aria-label="${ac(c.zh,c.name)}">${aerTail(code)}<span>${c.code}</span></button>`).join('')}</div><button class="aer-folio-button" type="button" data-project="aer">${ac('翻开作品档案','Open the project folio')} <span>↗</span></button></div><div class="aer-exhibit-inside"><div class="aer-inside-intro"><span class="aer-overline">THREE WAYS TO GET CLOSER</span><h4>${ac('旅程，还没起飞。<br>想象已经开始。','The journey is still ahead.<br>The imagination is already there.')}</h4></div><div class="aer-instruments"><section class="aer-glass-instrument"><span>01 / EXPLORE</span><div class="aer-mini-route"><strong>DXB</strong><svg viewBox="0 0 180 55" fill="none" aria-hidden="true"><path d="M5 42Q90 -18 175 42"/><path class="aer-orbit-trace" d="M5 42Q90 -18 175 42"/><circle cx="5" cy="42" r="3"/><circle cx="175" cy="42" r="3"/></svg><strong>LHR</strong></div><h5>${ac('先看见选择','A clearer choice')}</h5><p>${ac('搜索、筛选、排序和行程比较，在同一片清透的界面里展开。','Search, filter, sort and compare journeys in one clear space.')}</p><small>${ac('路线视觉示意 / 非实时航班','ROUTE STUDY / NOT A LIVE FLIGHT')}</small></section><section class="aer-glass-instrument"><span>02 / SIGNATURE</span><div class="aer-signature-art" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><b></b></div><h5>${ac('再找到自己的节奏','A traveller’s rhythm')}</h5><p>${ac('偏好、历史选择与反馈，连成可以继续生长的旅人星图。','Preferences, saved choices and feedback form an evolving traveller signature.')}</p></section><section class="aer-glass-instrument"><span>03 / FLEET ATLAS</span><div class="aer-aircraft-strip"><img src="${aerAsset}emirates-a380.webp" width="1600" height="505" alt="${ac('阿联酋航空 A380-800 侧面插画','Emirates A380-800 side illustration')}" loading="lazy"></div><h5>${ac('给每架飞机，准确的轮廓','The right aircraft, in view')}</h5><p>${ac('机型、航司与注册号分别核对，让涂装参考有清楚的来处。','Aircraft variant, operator and registration stay distinct, with visible provenance.')}</p></section></div>${actions()}<p class="aer-exhibit-note">${ac('AER 当前为私人站点。航班时刻与票价是演示数据，选中行程只保存意向记录；不创建预订、付款或机票。','AER is currently private. Schedules and fares are demonstrative; choosing a journey saves a shortlist entry without creating a reservation, payment or ticket.')}</p><div class="aer-art-credit">${ac('尾翼：AER 原项目的 logostream 航空插画。A380：','Tails: logostream illustrations from AER. A380: ')}<a href="https://commons.wikimedia.org/wiki/File:A380-Emirates.png" target="_blank" rel="noopener noreferrer">Fred053</a> / <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0</a> · ${ac('插画缩放为 WebP，标志归各航司所有。','Resized to WebP. Airline marks belong to their owners.')}</div></div></article>`;
}
export function aerDetail(){return `<section class="aer-detail" data-aer-display data-aer-airline="EK"><div class="aer-detail-heading"><span class="aer-overline">PROJECT FOLIO / 09 / V 1.0</span><h2 id="dialog-title">aer<span>®</span></h2><p>${ac('让下一程，更像你。','A journey that feels like you.')}</p></div>${aerScene()}<div class="aer-detail-body"><h3>${ac('一座关于出发的透明空间。','A clear space for a considered departure.')}</h3><p>${ac('AER 将航班探索、旅人档案、偏好与历史记录连在一起。你能比较行程、阅读推荐理由，再把一次选择留进自己的旅行签名。尾翼与机型插画沿用原项目的素材及来源，不用漂亮的图案替代准确的机型。','AER connects flight exploration with a traveller profile, preferences and history. Compare journeys, read the reasons behind recommendations and save a choice in your signature. Tail and aircraft imagery keep the original project’s sources and variant checks.')}</p><figure class="aer-screen-figure"><img src="${aerAsset}home.webp" width="1425" height="1460" alt="${ac('AER 1.0 本地演示界面','AER 1.0 local demonstration interface')}" loading="lazy"><figcaption>${ac('真实软件界面 / 本地演示航班与价格','ACTUAL APPLICATION / LOCAL DEMO FLIGHTS AND FARES')}</figcaption></figure>${actions()}<p class="aer-exhibit-note">${ac('站点需要授权访问。当前选择不会生成机票或支付订单。','The site requires authorised access. A selection does not create a ticket or payment order.')}</p></div></section>`;}
export function changeAerAirline(button){
  const host=button.closest('[data-aer-display]'),code=button.dataset.aerAirlineButton,c=aerCarriers[code];
  if(!host||!c||host.dataset.aerAirline===code)return;
  host.dataset.aerAirline=code;
  const tail=host.querySelector('.aer-main-fin .aer-tail'),image=tail?.querySelector('[data-tail-image]');
  if(image){image.getAnimations().forEach(a=>a.cancel());image.src=aerAsset+c.image;tail.style.setProperty('--tail-source',`url('${aerAsset+c.image}')`);if(canAnimate())image.animate([{opacity:.2,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:520,easing:'cubic-bezier(.22,.68,.25,1)'});}
  Object.keys(aerCarriers).filter(other=>other!==code).forEach((other,index)=>{const satellite=host.querySelector(index===0?'.aer-satellite--left .aer-tail':'.aer-satellite--right .aer-tail');if(satellite){satellite.style.setProperty('--tail-source',`url('${aerAsset+aerCarriers[other].image}')`);satellite.querySelector('img').src=aerAsset+aerCarriers[other].image;}});
  host.querySelector('[data-tail-caption]').textContent=c.name;
  host.querySelectorAll('[data-aer-airline-button]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
}
